const core1000ByChar = Object.fromEntries(core1000Meta.map(item => [item.char, item]));
const coreFrequencyRank = Object.fromEntries(core1000Meta.map(item => [item.char, item.rank]));
globalThis.core1000Meta = core1000Meta;
globalThis.core1000ByChar = core1000ByChar;
